/**
 * MemoryEngine — growth history (design doc §6, LLM-connected).
 *
 * Stores milestones, daily summaries, a growth timeline and weekly reports in
 * ~/.petdex/runtime/memory.json.
 *
 * Daily summaries and weekly reports are generated by the LLM from REAL
 * structured event aggregates (never from prompt/code/output text). When the
 * LLM is unavailable the engine falls back to a deterministic template, so
 * memory always works offline. Everything here is derived data: clearing it
 * never touches growth.json / career.json.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { RUNTIME_DIR } from "./paths.js";
import { CAREER_LABELS, type Career } from "./career.js";

export type Milestone = {
  id: string;
  type: string;
  title: string;
  description: string;
  createdAt: number;
};

export type DailySummary = {
  date: string;
  intensity: number;
  tasks: number;
  errors: number;
  recovered: number;
  dominantCareer: Career | null;
  summaryText: string;
  source: "llm" | "template";
};

export type TimelineEntry = {
  date: string;
  title: string;
  description: string;
  kind: "level" | "career" | "title" | "milestone" | "profile" | "weekly" | "system";
};

export type WeeklyReport = {
  week: string; // ISO week key e.g. "2026-W34"
  summaryText: string;
  source: "llm" | "template";
  createdAt: number;
};

/** LLM-generated growth narrative — analyzes habits to describe the growth arc. */
export type GrowthSummary = {
  id: string;
  createdAt: number;
  summaryText: string;
  source: "llm" | "template";
  range: { start: string; end: string };
};

export type MemoryData = {
  milestones: Milestone[];
  dailySummaries: DailySummary[];
  timeline: TimelineEntry[];
  weeklyReports: WeeklyReport[];
  growthSummaries: GrowthSummary[];
  updatedAt: number;
};

/** Facts about one day, built by index.ts from growth/career/stats. */
export type DailyFacts = {
  date: string;
  intensity: number;
  tasks: number;
  steps: number;
  tools: number;
  errors: number;
  recovered: number;
  approvals: number;
  questions: number;
  dominantCareer: Career | null;
  topTools: [string, number][];
};

/** Aggregate facts for the LLM growth narrative (built from growth/career/stats). */
export type GrowthFacts = {
  level: number;
  xp: number;
  bond: number;
  mood: string;
  energy: number;
  streakDays: number;
  intensityToday: number;
  intensity7: number;
  intensity30: number;
  tasksCompleted: number;
  errorsRecovered: number;
  errorRate: number;
  completionRate: number;
  avgToolChain: number;
  primaryCareer: Career | null;
  secondaryCareer: Career | null;
  title: string | null;
  careerXp: Record<Career, number>;
  profileTypeLabel: string | null;
  topTools: [string, number][];
  chronotype: string;
  peakHour: number;
};

export type LlmAsk = (prompt: string, opts?: { system?: string; maxLength?: number }) => Promise<string | null>;

const MEMORY_PATH = join(RUNTIME_DIR, "memory.json");

function emptyData(): MemoryData {
  return { milestones: [], dailySummaries: [], timeline: [], weeklyReports: [], growthSummaries: [], updatedAt: Date.now() };
}

export class MemoryEngine {
  private data: MemoryData;
  private dirty = false;
  private saveTimer: ReturnType<typeof setTimeout> | null = null;

  constructor() {
    this.data = this.load();
  }

  private load(): MemoryData {
    try {
      if (existsSync(MEMORY_PATH)) {
        const raw = JSON.parse(readFileSync(MEMORY_PATH, "utf8")) as Partial<MemoryData>;
        const base = emptyData();
        base.milestones = Array.isArray(raw.milestones) ? raw.milestones : [];
        base.dailySummaries = Array.isArray(raw.dailySummaries) ? raw.dailySummaries : [];
        base.timeline = Array.isArray(raw.timeline) ? raw.timeline : [];
        base.weeklyReports = Array.isArray(raw.weeklyReports) ? raw.weeklyReports : [];
        base.growthSummaries = Array.isArray(raw.growthSummaries) ? raw.growthSummaries : [];
        base.updatedAt = raw.updatedAt ?? Date.now();
        return base;
      }
    } catch {
      // corrupt file: start fresh
    }
    return emptyData();
  }

  private scheduleSave() {
    this.dirty = true;
    if (this.saveTimer) return;
    const timer = setTimeout(() => {
      this.saveTimer = null;
      if (!this.dirty) return;
      this.dirty = false;
      try {
        mkdirSync(RUNTIME_DIR, { recursive: true });
        this.data.updatedAt = Date.now();
        writeFileSync(MEMORY_PATH, JSON.stringify(this.data));
      } catch {
        // best-effort
      }
    }, 1000);
    if (typeof (timer as { unref?: () => void }).unref === "function") {
      (timer as { unref: () => void }).unref();
    }
    this.saveTimer = timer;
  }

  getData(): MemoryData {
    return this.data;
  }

  clear() {
    this.data = emptyData();
    this.dirty = true;
    this.scheduleSave();
  }

  /** Record a milestone (id dedupe happens in GrowthEngine's registry). */
  addMilestone(id: string, type: string, title: string, description: string, now = Date.now()) {
    if (this.data.milestones.some((m) => m.id === id)) return;
    this.data.milestones.unshift({ id, type, title, description, createdAt: now });
    if (this.data.milestones.length > 200) this.data.milestones.length = 200;
    // Milestones live in their own list; they are NOT mirrored into the
    // timeline — the timeline only records major, infrequent moments.
  }

  /** Add a major moment to the growth timeline (deduped, capped, low-frequency). */
  addTimeline(date: string, title: string, description: string, kind: TimelineEntry["kind"]) {
    // Coalesce: don't stack identical consecutive entries (e.g. repeated
    // "职业方向：X" flips) — keep only the most recent one.
    const head = this.data.timeline[0];
    if (head && head.title === title && head.kind === kind) {
      head.description = description;
      head.date = date;
      this.scheduleSave();
      return;
    }
    this.data.timeline.unshift({ date, title, description, kind });
    if (this.data.timeline.length > 150) this.data.timeline.length = 150;
    this.scheduleSave();
  }

  getSummary(date: string): DailySummary | undefined {
    return this.data.dailySummaries.find((s) => s.date === date);
  }

  /**
   * Generate (or regenerate) a day's summary. Prefers the LLM; falls back to
   * the design doc's template. Returns the created DailySummary.
   */
  async generateDailySummary(
    facts: DailyFacts,
    llmAsk: LlmAsk | null,
    llmEnabled: boolean,
  ): Promise<DailySummary> {
    const dominant = facts.dominantCareer ? CAREER_LABELS[facts.dominantCareer] : "综合";
    const topTools = facts.topTools.slice(0, 5).map(([n, c]) => `${n}×${c}`).join("、") || "—";

    let text = "";
    let source: "llm" | "template" = "template";
    if (llmEnabled && llmAsk) {
      const prompt =
        `今天是 ${facts.date}。请以宠物鲸鱼的口吻，根据下面的真实工作统计数据，写一段 2-4 句的中文日记（像鲸鱼在记录主人这一天的工作，真诚、有温度），` +
        `并在最后单独一行写「洞察：」加 1 条简短的工作建议。只输出日记与洞察，不要其他内容。\n\n` +
        `今日数据：\n` +
        `- 任务完成：${facts.tasks} 个\n` +
        `- 步骤：${facts.steps} 步\n` +
        `- 工具调用：${facts.tools} 次（常用：${topTools}）\n` +
        `- 错误：${facts.errors} 次，成功恢复 ${facts.recovered} 次\n` +
        `- 审批 ${facts.approvals} 次 / 提问 ${facts.questions} 次\n` +
        `- 今日工作强度：${Math.round(facts.intensity)}\n` +
        `- 主要职业方向：${dominant}`;
      const reply = await llmAsk(prompt, { maxLength: 600 });
      if (reply) {
        text = reply;
        source = "llm";
      }
    }
    if (!text) {
      text =
        `今天小鲸鱼主要参与了 ${dominant} 类任务。它完成了 ${facts.tasks} 个任务，` +
        `恢复了 ${facts.recovered} 次错误。今日贡献强度为 ${Math.round(facts.intensity)}。`;
    }

    const idx = this.data.dailySummaries.findIndex((s) => s.date === facts.date);
    const summary: DailySummary = {
      date: facts.date,
      intensity: Math.round(facts.intensity),
      tasks: facts.tasks,
      errors: facts.errors,
      recovered: facts.recovered,
      dominantCareer: facts.dominantCareer,
      summaryText: text,
      source,
    };
    if (idx >= 0) this.data.dailySummaries[idx] = summary;
    else this.data.dailySummaries.unshift(summary);
    if (this.data.dailySummaries.length > 120) this.data.dailySummaries.length = 120;
    this.scheduleSave();
    return summary;
  }

  /** Weekly report (every 7 active days / manual). LLM-preferred. */
  async generateWeeklyReport(
    facts: { start: string; end: string; days: DailyFacts[]; totalIntensity: number; topTools: [string, number][] },
    llmAsk: LlmAsk | null,
    llmEnabled: boolean,
  ): Promise<WeeklyReport> {
    const week = `${facts.start.slice(0, 7)}-W${isoWeek(new Date(facts.end + "T12:00:00"))}`;
    const totalTasks = facts.days.reduce((s, d) => s + d.tasks, 0);
    const totalErrors = facts.days.reduce((s, d) => s + d.errors, 0);
    const totalRecovered = facts.days.reduce((s, d) => s + d.recovered, 0);
    const tools = facts.topTools.slice(0, 6).map(([n, c]) => `${n}×${c}`).join("、") || "—";

    let text = "";
    let source: "llm" | "template" = "template";
    if (llmEnabled && llmAsk) {
      const prompt =
        `请以宠物鲸鱼的口吻，根据这一周（${facts.start} 至 ${facts.end}）的真实工作统计数据，写一份 3-5 句的中文周报，` +
        `总结主人的工作模式与亮点，并给出 1 条成长建议。只输出周报正文。\n\n` +
        `周数据：\n` +
        `- 活跃天数：${facts.days.length} 天\n` +
        `- 完成任务：${totalTasks} 个\n` +
        `- 错误：${totalErrors} 次，恢复 ${totalRecovered} 次\n` +
        `- 周总强度：${Math.round(facts.totalIntensity)}\n` +
        `- 常用工具：${tools}\n` +
        `- 每日数据：${facts.days.map((d) => `${d.date}(任务${d.tasks}/强度${Math.round(d.intensity)})`).join("，")}`;
      const reply = await llmAsk(prompt, { maxLength: 700 });
      if (reply) {
        text = reply;
        source = "llm";
      }
    }
    if (!text) {
      text =
        `本周（${facts.start} 至 ${facts.end}）主人活跃了 ${facts.days.length} 天，完成 ${totalTasks} 个任务，` +
        `累计工作强度 ${Math.round(facts.totalIntensity)}。错误恢复 ${totalRecovered}/${totalErrors} 次。`;
    }

    const report: WeeklyReport = { week, summaryText: text, source, createdAt: Date.now() };
    this.data.weeklyReports.unshift(report);
    if (this.data.weeklyReports.length > 40) this.data.weeklyReports.length = 40;
    this.addTimeline(dayStr(Date.now()), `周报 · ${facts.start}`, text.slice(0, 120), "weekly");
    this.scheduleSave();
    return report;
  }

  /**
   * LLM growth narrative — the centerpiece "成长综述". Analyzes the user's REAL
   * habits + growth data and writes a personalized 3-6 sentence description of
   * their growth arc (career direction, rhythm, quality trend, next step). Falls
   * back to a deterministic template when the LLM is unavailable.
   */
  async generateGrowthSummary(
    facts: GrowthFacts,
    llmAsk: LlmAsk | null,
    llmEnabled: boolean,
  ): Promise<GrowthSummary> {
    const primary = facts.primaryCareer ? CAREER_LABELS[facts.primaryCareer] : "综合";
    const secondary = facts.secondaryCareer ? CAREER_LABELS[facts.secondaryCareer] : "—";
    const careerDist = (Object.entries(facts.careerXp) as [Career, number][])
      .filter(([, v]) => v > 0)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 4)
      .map(([c, v]) => `${CAREER_LABELS[c]} ${Math.round(v)}`)
      .join("、") || "尚未形成明显倾向";
    const tools = facts.topTools.slice(0, 6).map(([n, c]) => `${n}×${c}`).join("、") || "—";

    let text = "";
    let source: "llm" | "template" = "template";
    if (llmEnabled && llmAsk) {
      const prompt =
        `请以宠物鲸鱼的口吻，基于主人的真实使用习惯与成长数据，写一段 3-6 句的中文「成长综述」，` +
        `分析主人最近的工作方式、成长轨迹与风格倾向，并给出 1 条下一阶段建议。` +
        `只输出正文，不要标题、不要列表符号。必须只依据下面给出的真实数据，不要编造。\n\n` +
        `成长与习惯数据：\n` +
        `- 等级 Lv.${facts.level}，累计 XP ${Math.round(facts.xp)}，亲密度 ${Math.round(facts.bond)}，连续使用 ${facts.streakDays} 天\n` +
        `- 今日强度 ${facts.intensityToday}，近 7 天 ${facts.intensity7}，近 30 天 ${facts.intensity30}\n` +
        `- 完成任务 ${facts.tasksCompleted} 个，错误恢复 ${facts.errorsRecovered} 次\n` +
        `- 错误率 ${Math.round(facts.errorRate * 1000) / 10}%，任务完成率 ${Math.round(facts.completionRate * 1000) / 10}%，平均工具链 ${facts.avgToolChain}\n` +
        `- 主职业：${primary}，副职业：${secondary}，称号：${facts.title ?? "—"}\n` +
        `- 职业 XP：${careerDist}\n` +
        `- 用户画像：${facts.profileTypeLabel ?? "尚未生成"}\n` +
        `- 作息：${facts.chronotype}，活跃峰值约 ${facts.peakHour} 点\n` +
        `- 常用工具：${tools}\n` +
        `- 当前心情：${facts.mood}，精力：${facts.energy}`;
      const reply = await llmAsk(prompt, { maxLength: 900 });
      if (reply) {
        text = reply;
        source = "llm";
      }
    }
    if (!text) {
      text =
        `小鲸鱼正在成长为「${primary}」型伙伴。累计完成 ${facts.tasksCompleted} 个任务、恢复 ${facts.errorsRecovered} 次错误，` +
        `近 7 天工作强度 ${facts.intensity7}，作息偏「${facts.chronotype}」。建议继续保持当前的 ${primary} 方向，` +
        `在活跃峰值时段（约 ${facts.peakHour} 点）处理高复杂度任务。`;
    }

    const summary: GrowthSummary = {
      id: `g${Date.now()}`,
      createdAt: Date.now(),
      summaryText: text,
      source,
      range: { start: dayStr(Date.now() - 7 * 24 * 3600 * 1000), end: dayStr(Date.now()) },
    };
    this.data.growthSummaries.unshift(summary);
    if (this.data.growthSummaries.length > 20) this.data.growthSummaries.length = 20;
    this.scheduleSave();
    return summary;
  }

  /** Enrich a milestone's description with an LLM narrative (fallback keeps the template). */
  async enrichMilestone(
    id: string,
    factsPrompt: string,
    llmAsk: LlmAsk | null,
    llmEnabled: boolean,
  ): Promise<void> {
    const m = this.data.milestones.find((x) => x.id === id);
    if (!m) return;
    if (!llmEnabled || !llmAsk) return;
    const prompt =
      `主人刚刚达成一个成长里程碑「${m.title}」。请结合主人当前的使用习惯，用一两句中文给这个里程碑写一个个性化的描述，` +
      `体现这是「主人的真实习惯塑造的成长节点」。只输出描述文字。\n\n当前习惯数据：\n${factsPrompt}`;
    const reply = await llmAsk(prompt, { maxLength: 160 });
    if (!reply) return;
    m.description = reply;
    this.scheduleSave();
  }

  /** Enrich the most recent timeline entry with a given title via an LLM narrative. */
  async enrichTimeline(
    title: string,
    prompt: string,
    llmAsk: LlmAsk | null,
    llmEnabled: boolean,
  ): Promise<void> {
    if (!llmEnabled || !llmAsk) return;
    const tl = this.data.timeline.find((t) => t.title === title);
    if (!tl) return;
    const reply = await llmAsk(prompt, { maxLength: 200 });
    if (reply) {
      tl.description = reply;
      this.scheduleSave();
    }
  }
}

function dayStr(ts: number): string {
  const d = new Date(ts);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

function isoWeek(d: Date): number {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil(((date.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
}
